"use client";

import { Plot as PlotPrimitive } from "@audio-ui/react";
import { cn } from "@/lib/utils";

/** The frame: give it a width and a height, draw in it with the parts below. */
function Plot({ className, ...props }: PlotPrimitive.Root.Props) {
  return (
    <PlotPrimitive.Root
      className={cn(
        "rounded-xl border bg-card relative h-48 w-full touch-none select-none data-disabled:opacity-50",
        className
      )}
      data-slot="plot"
      {...props}
    />
  );
}

function PlotGraph({ className, ...props }: PlotPrimitive.Graph.Props) {
  return (
    <PlotPrimitive.Graph
      className={cn("text-primary", className)}
      data-slot="plot-graph"
      {...props}
    />
  );
}

/** A curve: `y = fn(x)` across the plot. */
function PlotCurve({ className, ...props }: PlotPrimitive.Curve.Props) {
  return (
    <PlotPrimitive.Curve
      className={cn("stroke-primary stroke-[1.5px] fill-none", className)}
      data-slot="plot-curve"
      {...props}
    />
  );
}

/** The same, filled down to `fillTo`: draw it under a `PlotCurve`. */
function PlotArea({ className, ...props }: PlotPrimitive.Curve.Props) {
  return (
    <PlotPrimitive.Curve
      className={cn("fill-primary/15 stroke-none", className)}
      data-slot="plot-area"
      {...props}
    />
  );
}

/** A rule at a value: 0 dB, a cutoff, a threshold. */
function PlotLine({ className, ...props }: PlotPrimitive.Line.Props) {
  return (
    <PlotPrimitive.Line
      className={cn("stroke-border", className)}
      data-slot="plot-line"
      {...props}
    />
  );
}

/** A shaded stretch of one axis. */
function PlotBand({ className, ...props }: PlotPrimitive.Band.Props) {
  return (
    <PlotPrimitive.Band
      className={cn("fill-foreground/5", className)}
      data-slot="plot-band"
      {...props}
    />
  );
}

/** A point to drag: a band, a cutoff, a threshold. Arrow keys move it too. */
function PlotHandle({ className, ...props }: PlotPrimitive.Handle.Props) {
  return (
    <PlotPrimitive.Handle
      className={cn(
        "rounded-full border-2 border-primary bg-background shadow-xs transition-[box-shadow] duration-150 ease-out hover:ring-4 hover:ring-ring/30 focus-within:ring-4 focus-within:ring-ring/30 data-dragging:ring-4 data-dragging:ring-ring/30 motion-reduce:transition-none size-4 cursor-grab outline-none after:absolute after:-inset-2 data-dragging:cursor-grabbing data-disabled:pointer-events-none",
        className
      )}
      data-slot="plot-handle"
      {...props}
    />
  );
}

export { Plot, PlotArea, PlotBand, PlotCurve, PlotGraph, PlotHandle, PlotLine };

"use client";

import { useCallback, useMemo, useState } from "react";
import {
  Plot,
  PlotArea,
  PlotCurve,
  PlotGraph,
  PlotHandle,
  PlotLine,
} from "@/components/audio/elements/plot";
import {
  type EqBand,
  eqResponse,
  formatDb,
  formatHz,
} from "@/lib/filter-response";

const BANDS: EqBand[] = [
  { frequency: 90, gainDb: 3, type: "lowshelf" },
  { frequency: 1200, gainDb: -4, q: 1.2, type: "peak" },
  { frequency: 7000, gainDb: 5, type: "highshelf" },
];
const MIN_HZ = 20;
const MAX_HZ = 20_000;
const MAX_DB = 18;
const DB_LABELS = [-12, 0, 12];

const describeValue = (value: number, axis: "x" | "y") =>
  axis === "x" ? formatHz(value) : formatDb(value);

interface BandHandleProps {
  band: EqBand;
  index: number;
  onChange: (index: number, frequency: number, gainDb: number) => void;
}

/** One band's handle: its frequency across, its gain up. */
function BandHandle({ band, index, onChange }: BandHandleProps) {
  const handleChange = useCallback(
    ({ x, y }: { x: number; y: number }) => onChange(index, x, y),
    [index, onChange]
  );
  return (
    <PlotHandle
      aria-label={`Band ${index + 1}`}
      getAriaValueText={describeValue}
      onValueChange={handleChange}
      value={{ x: band.frequency, y: band.gainDb ?? 0 }}
    />
  );
}

/** An equalizer: drag each band to set its frequency and gain; the curve is the response of all three. */
export function PlotDemo() {
  const [bands, setBands] = useState(BANDS);
  const [selected, setSelected] = useState(1);
  const response = useMemo(() => eqResponse(bands), [bands]);
  const changeBand = useCallback(
    (index: number, frequency: number, gainDb: number) => {
      setSelected(index);
      setBands((current) =>
        current.map((other, at) =>
          at === index ? { ...other, frequency, gainDb } : other
        )
      );
    },
    []
  );
  const band = bands[selected];

  return (
    <div className="flex w-full max-w-xl flex-col gap-2">
      <Plot
        maxX={MAX_HZ}
        maxY={MAX_DB}
        minX={MIN_HZ}
        minY={-MAX_DB}
        scaleX="log"
      >
        <PlotGraph>
          {DB_LABELS.map((db) => (
            <PlotLine axis="y" key={db} value={db} />
          ))}
          <PlotArea fillTo={0} fn={response} />
          <PlotCurve fn={response} />
        </PlotGraph>
        {bands.map((item, index) => (
          <BandHandle
            band={item}
            index={index}
            // The bands never come or go, so their order is their identity.
            // biome-ignore lint/suspicious/noArrayIndexKey: fixed list.
            key={index}
            onChange={changeBand}
          />
        ))}
      </Plot>
      <output className="text-center font-mono text-muted-foreground text-xs">
        Band {selected + 1}: {formatHz(band?.frequency ?? 0)},{" "}
        {formatDb(band?.gainDb ?? 0)}
      </output>
    </div>
  );
}
